INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (2, 2, 3000, 2, "vo_minigame_1013_icon_2_002_001", "vo_minigame_1013_icon_1_002_001", "訓練はまだ\nここからですわ", 1, "調子が上がって\nきたなっ", 1000);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (2, 2, 3000, 2, "vo_minigame_1013_icon_2_003_001", "vo_minigame_1013_icon_1_003_001", "クスクス、悪くない\n流れですわね", 2, "ほらほら、\nまだいけるだろ？", 5000);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (2, 2, 3000, 3, "vo_minigame_1013_icon_2_004_001", "vo_minigame_1013_icon_1_004_001", "すばらしい\n記録ですわ", 3, "へへっ、おまえら\nやるじゃねえか！", 10000);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (3, 2, 3000, 3, "vo_minigame_1013_icon_2_005_001", "vo_minigame_1013_icon_1_005_001", "乗りに乗って\nいますわね", 4, "あたしたちはまだ\n止まらねえぜ！", 10000);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (3, 2, 3000, 3, "vo_minigame_1013_icon_2_005_002", "vo_minigame_1013_icon_1_005_002", "まだまだ行きます\nついてきなさい", 5, "見てろよ！\nマコト班の快進撃だ！", 10000);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (3, 2, 3000, 3, "vo_minigame_1013_icon_2_005_003", "vo_minigame_1013_icon_1_005_003", "エリコ班の\n本領発揮ですわ！", 6, "うおぉぉっ！\n絶好調だぜ！", 10000);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (4, 2, 3000, 3, "vo_minigame_1013_icon_2_006_001", "vo_minigame_1013_icon_1_006_001", "ここからは\n前人未到の領域です！", 7, "どこまで行けるか\n楽しみだなっ！", 0);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (5, 3, 1000, 4, "vo_minigame_1013_icon_2_007_001", "vo_minigame_1013_icon_1_007_001", "厄介でしたわ…", 8, "まだ諦めんなよっ", 1);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (5, 3, 1000, 4, "vo_minigame_1013_icon_2_007_002", "vo_minigame_1013_icon_1_007_002", "油断大敵です", 9, "冷やっとしたぜ…！", 1);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (5, 3, 1000, 4, "vo_minigame_1013_icon_2_007_003", "vo_minigame_1013_icon_1_007_003", "忌々しいっ…", 10, "弱音を吐くなっ", 1);
